add_action( 'woocommerce_thankyou', 'perfectpixel_logout_after_checkout_flag' );
add_action( 'template_redirect', 'perfectpixel_logout_after_checkout_run' );

function perfectpixel_logout_after_checkout_should_apply() {
	$user = wp_get_current_user();
	return $user->exists() && in_array( 'customer', (array) $user->roles, true ) && ! current_user_can( 'edit_posts' );
}

function perfectpixel_logout_after_checkout_flag() {
	if ( perfectpixel_logout_after_checkout_should_apply() ) {
		update_user_meta( get_current_user_id(), '_perfectpixel_logout_next', 1 );
	}
}

function perfectpixel_logout_after_checkout_run() {
	if ( ! is_user_logged_in() || is_wc_endpoint_url( 'order-received' ) ) {
		return;
	}
	$user_id = get_current_user_id();
	if ( get_user_meta( $user_id, '_perfectpixel_logout_next', true ) ) {
		delete_user_meta( $user_id, '_perfectpixel_logout_next' );
		wp_logout();
		// Reload the same page, now logged out.
		wp_safe_redirect( esc_url_raw( wp_unslash( $_SERVER['REQUEST_URI'] ?? '/' ) ) ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput
		exit;
	}
}
